const TRANSIENT = new Set(['TIMEOUT','L4_TIMEOUT','E_SPILL_IO','E_WCB_TIMEOUT','RATE_LIMIT','HTTP_429','HTTP_500','HTTP_502','HTTP_503','HTTP_504']);
const CORRUPT = new Set(['E_SPILL_CORRUPT','CHECKSUM_MISMATCH','INVALID_MAGIC','OFFSET_OUT_OF_RANGE','L4_PARSE']);
const DENIED = new Set(['L4_EVAL_DENIED','L4_NAV_BLOCKED','AUTH_FAILED','HTTP_401','HTTP_403','HTTP_404','VALIDATION_ERROR']);

function classify(code, attempt) {
  const a = Math.max(1, attempt | 0);
  if (CORRUPT.has(code)) {
    return { retryable: false, retry_after_ms: 0, route: 'dead_letter', severity: 'critical', reason: 'corrupt-quarantine' };
  }
  if (DENIED.has(code)) {
    return { retryable: false, retry_after_ms: 0, route: 'dead_letter', severity: 'high', reason: 'policy-denied' };
  }
  if (TRANSIENT.has(code)) {
    const backoff = Math.min(Math.pow(2, a - 1) * 1000, 30000);
    return { retryable: true, retry_after_ms: backoff, route: 'retry_queue', severity: 'medium', reason: 'transient-backoff' };
  }
  return { retryable: false, retry_after_ms: 0, route: 'dead_letter', severity: 'high', reason: 'unknown-fail-closed' };
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const code = String(j.error_code || 'UNKNOWN');
  const attempt = Number(j.attempt || 1);
  const d = classify(code, attempt);
  out.push({ json: { error_code: code, attempt: attempt, retryable: d.retryable, retry_after_ms: d.retry_after_ms, route: d.route, severity: d.severity, reason: d.reason } });
}
return out;
